[
  {
    "text": "Self-Guided Test-Time Training (S-TTT) improves accuracy on LongBench-v2 and LongBench-Pro benchmarks by up to 15% relative improvement for Qwen3-4B-Thinking-2507 and Llama-3.1-8B-Instruct.",
    "topic": "Self-Guided Test-Time Training"
  },
  {
    "text": "Test-Time Training (TTT) applied to randomly sampled spans in long contexts degrades performance, while TTT on oracle spans substantially improves it.",
    "topic": "Test-Time Training Sensitivity"
  },
  {
    "text": "S-TTT selects evidence spans that the model should learn from before applying the standard language-modeling training objective, improving long-context utilization.",
    "topic": "Self-Guided Span Selection"
  },
  {
    "text": "Long context windows can bury decision-relevant information, and the quadratic cost of self-attention limits training and inference on long sequences.",
    "topic": "Long-Context Memory Challenges"
  },
  {
    "text": "ReContext improves evidence utilization across Qwen3-4B, Qwen3-8B, and Llama3-8B on eight long-context datasets with 128K context length.",
    "topic": "ReContext Performance"
  }
]
